164	// FetchBlobs fetches specific objects (typically blobs) by hash from a remote.
165	// Uses `git fetch-pack` rather than `git fetch` because the high-level
166	// porcelain enforces partial-clone integrity checks that reject blob-only
167	// responses with "did not send all necessary objects". Plumbing skips those
168	// checks — it just downloads the requested objects into .git/objects/pack
169	// and exits — which is exactly what we want when grabbing individual blobs
170	// by SHA. Works against GitHub for any reachable object, including blobs.
171	//
172	// The remote should be a URL (not a remote name) to avoid persisting promisor
173	// settings onto the named remote. Use FetchURL to obtain the URL.
174	func FetchBlobs(ctx context.Context, remote string, hashes []string) error {
175		args := []string{"fetch-pack", remote}
176		args = append(args, hashes...)
177	
178		cmd := newCommand(ctx, args...)
179		disableTerminalPrompt(cmd)
180		output, err := cmd.CombinedOutput()
181		if err != nil {
182			redactedURL := RedactURL(remote)
183			msg := strings.TrimSpace(strings.ReplaceAll(string(output), remote, redactedURL))
184			if msg != "" {
185				return fmt.Errorf("git fetch-pack from %s: %s: %w", redactedURL, msg, err)
186			}
187			return fmt.Errorf("git fetch-pack from %s: %w", redactedURL, err)
188		}
189		return nil
190	}
