258	// IsURL returns true if the target looks like a URL rather than a git remote name.
259	func IsURL(target string) bool {
260		return strings.Contains(target, "://") || strings.Contains(target, "@")
261	}
262	
263	// ResolveFetchTarget returns the git fetch target to use. When filtered
264	// fetches are enabled, configured remotes are resolved to their URL so git does
265	// not persist promisor settings onto the remote name.
266	func ResolveFetchTarget(ctx context.Context, target string) (string, error) {
267		if IsURL(target) || isLocalPath(target) || !settings.IsFilteredFetchesEnabled(ctx) {
268			return target, nil
269		}
270		url, err := GetRemoteURL(ctx, target)
271		if err != nil {
272			return "", fmt.Errorf("get remote URL: %w", err)
273		}
274		return url, nil
275	}
276	
277	// isShallowRepository returns true when the git repository at dir is shallow.
278	// An empty dir inherits the parent process's working directory, matching the
279	// semantics callers use when invoking Fetch with empty FetchOptions.Dir.
280	func isShallowRepository(ctx context.Context, dir string) bool {
281		cmd := exec.CommandContext(ctx, "git", "rev-parse", "--is-shallow-repository")
282		cmd.Dir = dir
283		disableTerminalPrompt(cmd)
284		out, err := cmd.Output()
285		if err != nil {
286			return false
287		}
288		return strings.TrimSpace(string(out)) == "true"
289	}
