func gitConfigBool(ctx context.Context, dir, key string) bool {
	cmd := exec.CommandContext(ctx, "git", "config", "--local", "--get", "--type=bool", key)
	if dir != "" {
		cmd.Dir = dir
	}
	out, err := cmd.Output()
	if err != nil {
		return false
	}
	return strings.TrimSpace(string(out)) == "true"
